import workcell, time, json

def lift_to_safe(zmin=150):
    for _ in range(30):
        r=workcell.call('arm','step','+5')
        if not r.ok:
            print('lift fail', r.text); return False
        z=r.data.get('z_mm')
        if z is not None and z>=zmin-0.5:
            return True
    return True

def coarse_probe(x,y):
    r=workcell.call('arm','move',str(x),str(y),'150')
    if not r.ok:
        print('MOVE FAIL',x,y,r.text); return None
    workcell.call('ft','zero')
    # step -5 until contact or z<=55
    for i in range(40):
        r=workcell.call('arm','step','-5')
        if not r.ok:
            print('STEP FAIL',x,y,r.text); break
        z=r.data.get('z_mm'); fz=r.data.get('fz_N')
        if fz is not None and fz>0.5:
            lift_to_safe()
            return {'x':x,'y':y,'z_contact_rough':z,'fz':fz,'steps':i+1}
        if z is not None and z<=55:
            lift_to_safe()
            return {'x':x,'y':y,'z_contact_rough':z,'fz':fz,'steps':i+1,'no_contact':True}
    lift_to_safe()
    return {'x':x,'y':y,'error':'too many'}

points=[]
for y in [-60,-50,-40,-30,-20,-10,0,10,15,20,25,30,40]:
    points.append((570,y))
for x in [530,550,590,610,630]:
    points.append((x,-10))

results=[]
for x,y in points:
    res=coarse_probe(x,y)
    print(res)
    results.append(res)

# ensure at safe
workcell.call('arm','move','570','-10','150')
print(json.dumps(results, indent=2))
